  EventType extends keyof HTMLElementEventMap,
>(
  ref: RefObject<ElementType | null> | Document | Window,
  event: EventType,
  // oxlint-disable-next-line typescript/no-explicit-any
  callback: (this: ElementType, ev: HTMLElementEventMap[EventType]) => any,
) {
  // Keep the latest callback in a ref so the listener doesn't need to be
  // re-added when it changes. Callers routinely pass a new inline function
  // every render, which would otherwise tear down and re-add the native
  // listener on every render.
  const callbackRef = useRef(callback);
  callbackRef.current = callback;

  const attachedRef = useRef<{
    el: EventTarget;
    event: EventType;
    listener: EventListener;
  } | null>(null);

  // The element behind `ref` can be swapped out without the ref object itself
  // changing (e.g. when a component remounts the node it's attached to), so
  // check after every render and re-bind only when the target changed.
  useEffect(() => {
    const el =
      ref instanceof Document || ref instanceof Window ? ref : ref.current;
    const attached = attachedRef.current;
    if (attached && attached.el === el && attached.event === event) return;

    if (attached) {
      attached.el.removeEventListener(attached.event, attached.listener);
      attachedRef.current = null;
    }
    if (!el) return;

    const listener: EventListener = e =>
      callbackRef.current.call(
        el as ElementType,
        e as HTMLElementEventMap[EventType],
      );
    el.addEventListener(event, listener);
    attachedRef.current = { el, event, listener };
  });

  useEffect(() => {
    return () => {
      const attached = attachedRef.current;
      if (attached) {
        attached.el.removeEventListener(attached.event, attached.listener);
        attachedRef.current = null;
      }
    };
  }, []);
}

